    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 4,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 1</span>  و  <span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">AD.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AD.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">24</span><span class=\"den\">5</span></span>. و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث ADE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">B ∈ (AD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (AE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AB</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AC</span><span class=\"den\">AE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BC</span><span class=\"den\">DE</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">4</span><span class=\"den\">5</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">4,8</span><span class=\"den\">AD</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AD = 6</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AD = 6</span>"},{"quoi":"2)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">x = AC.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">AC.</span> نختار النّسبة و الجزء الباقي لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 1.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث ADE لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">B ∈ (AD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">C ∈ (AE)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AB</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AC</span><span class=\"den\">AE</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">BC</span><span class=\"den\">DE</span></span>"},{"quoi":"القاعدة","math":"إذا عُلمت النّسبة و عُلم الجزء الباقي، أمكن حساب الطولين"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">(BC) // (DE)</span>  و  <span dir=\"ltr\" class=\"expr pt\">BC = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">DE = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">CE = 1</span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AC = 4</span>  ، لأنّ النّسبة <span class=\"frac\" dir=\"ltr\"><span class=\"num\">4</span><span class=\"den\">5</span></span> و الفرق 1"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AC = 4</span>"}],
